<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue';
import api from '../api/client';
import { useRoute } from 'vue-router';
import ActivityCalendar from '../components/progress/ActivityCalendar.vue';
import LineChart from '../components/progress/LineChart.vue';
import BaseModal from '../components/common/BaseModal.vue';
import EmptyState from '../components/common/EmptyState.vue';
import LoadingSkeleton from '../components/common/LoadingSkeleton.vue';
import { useNotificationStore } from '../stores/notifications';
import { errorMessage } from '../utils/errors';
import { formatDay } from '../utils/dates';
const volume=ref(null); const volumeLoading=ref(false);
const route=useRoute();
const notifications=useNotificationStore(); const loading=ref(true); const tab=ref('overview'); const overview=ref({}); const activity=ref([]); const body=ref({data:[],summary:{}}); const exercises=ref([]); const achievements=ref([]); const recommendations=ref([]); const selectedExercise=ref(null); const exerciseData=ref(null); const measurementOpen=ref(false); const editingMeasurement=ref(null); const emptyMeasurement=()=>({recorded_on:new Date().toISOString().slice(0,10),body_weight_kg:null,waist_cm:null,body_fat_percentage:null,fat_mass_kg:null,lean_mass_kg:null,skeletal_muscle_mass_kg:null,total_body_water_kg:null,visceral_fat_level:null,basal_metabolic_rate_kcal:null,notes:null}); const measurement=reactive(emptyMeasurement());
const bodyLabels=computed(()=>body.value.data.map(item=>item.recorded_on)); const bodyDatasets=computed(()=>[{label:'Peso (kg)',yAxisID:'y',data:body.value.data.map(item=>item.body_weight_kg)},{label:'Cintura (cm)',yAxisID:'y1',data:body.value.data.map(item=>item.waist_cm)}]);
const compositionDatasets=computed(()=>[{label:'% Grasa',data:body.value.data.map(item=>item.body_fat_percentage)},{label:'Músculo esqueletico (kg)',data:body.value.data.map(item=>item.skeletal_muscle_mass_kg)},{label:'Masa magra (kg)',data:body.value.data.map(item=>item.lean_mass_kg)}]);
const hasComposition=computed(()=>body.value.data.some(item=>item.body_fat_percentage!=null||item.skeletal_muscle_mass_kg!=null));
const fmt=value=>value==null||value===''?'—':String(+Number(value).toFixed(2));
function trendInfo(field){const values=body.value.data.map(item=>item[field]).filter(value=>value!=null).map(Number);if(values.length<2)return{icon:'fa-minus text-secondary',label:'Sin tendencia'};const delta=values.at(-1)-values.at(-2);if(Math.abs(delta)<.05)return{icon:'fa-arrow-right text-secondary',label:'Estable'};return delta>0?{icon:'fa-arrow-trend-up',label:`Sube ${Math.abs(delta).toFixed(1)}`}:{icon:'fa-arrow-trend-down',label:`Baja ${Math.abs(delta).toFixed(1)}`};}
function compareRow(label,unit,field,initial,current,better){const hasBoth=initial!=null&&current!=null;const delta=hasBoth?Number(current)-Number(initial):null;const deltaClass=delta==null||Math.abs(delta)<.05||!better?'':((better==='down')===(delta<0)?(better==='down'?'delta-down':'delta-up'):'');return{label,unit,initial,current,delta:delta==null?'—':`${delta>0?'+':''}${delta.toFixed(1)}`,deltaClass,trend:trendInfo(field)};}
const compareRows=computed(()=>{const s=body.value.summary||{};const rows=[compareRow('Peso','kg','body_weight_kg',s.initial_weight,s.current_weight,null),compareRow('Cintura','cm','waist_cm',s.initial_waist,s.current_waist,'down')];if(hasComposition.value)rows.push(compareRow('Grasa corporal','%','body_fat_percentage',s.initial_body_fat,s.current_body_fat,'down'),compareRow('Músculo esquelético','kg','skeletal_muscle_mass_kg',s.initial_muscle,s.current_muscle,'up'),compareRow('Masa magra','kg','lean_mass_kg',null,s.current_lean_mass,null),compareRow('Agua corporal','kg','total_body_water_kg',null,s.current_body_water,null),compareRow('Grasa visceral','nivel','visceral_fat_level',null,s.current_visceral_fat,null),compareRow('Metabolismo basal','kcal','basal_metabolic_rate_kcal',null,s.current_bmr,null));return rows;});

const exerciseLabels=computed(()=>exerciseData.value?.series.map(item=>item.date)||[]); const exerciseDatasets=computed(()=>[{label:'Peso máximo',data:exerciseData.value?.series.map(item=>item.max_weight)||[]},{label:'Repeticiones totales',data:exerciseData.value?.series.map(item=>item.total_repetitions)||[]},{label:'Volumen',data:exerciseData.value?.series.map(item=>item.volume)||[]},{label:'1RM estimado',data:exerciseData.value?.series.map(item=>item.estimated_one_rep_max)||[]}]);
async function load(){loading.value=true;try{const [a,b,c,d,e,f]=await Promise.all([api.get('/progress/overview'),api.get('/progress/activity-calendar'),api.get('/progress/body'),api.get('/progress/exercises'),api.get('/game/achievements'),api.get('/progression/recommendations',{params:{status:'accepted'}})]);overview.value=a.data;activity.value=b.data.data;body.value=c.data;exercises.value=d.data.data;achievements.value=e.data.data;recommendations.value=f.data.data;if(exercises.value.length&&!selectedExercise.value){const requested=Number(route.query.exercise);selectedExercise.value=exercises.value.some(item=>item.id===requested)?requested:exercises.value[0].id;await loadExercise();}}catch(e){notifications.push(errorMessage(e),'error');}finally{loading.value=false;}}
async function loadExercise(){if(!selectedExercise.value)return;try{exerciseData.value=(await api.get(`/progress/exercises/${selectedExercise.value}`)).data;}catch(e){notifications.push(errorMessage(e),'error');}}
function openMeasurement(item=null){editingMeasurement.value=item;Object.assign(measurement,emptyMeasurement(),item?{recorded_on:item.recorded_on,body_weight_kg:item.body_weight_kg,waist_cm:item.waist_cm,body_fat_percentage:item.body_fat_percentage,fat_mass_kg:item.fat_mass_kg,lean_mass_kg:item.lean_mass_kg,skeletal_muscle_mass_kg:item.skeletal_muscle_mass_kg,total_body_water_kg:item.total_body_water_kg,visceral_fat_level:item.visceral_fat_level,basal_metabolic_rate_kcal:item.basal_metabolic_rate_kcal,notes:item.notes}:{});measurementOpen.value=true;}
async function saveMeasurement(){try{if(editingMeasurement.value)await api.put(`/body-measurements/${editingMeasurement.value.id}`,measurement);else await api.post('/body-measurements',measurement);measurementOpen.value=false;notifications.push(editingMeasurement.value?'Medición actualizada.':'Medición registrada.');await load();}catch(e){notifications.push(errorMessage(e),'error');}}
async function removeMeasurement(item){if(!confirm('Eliminar esta medición?'))return;try{await api.delete(`/body-measurements/${item.id}`);notifications.push('Medición eliminada.');await load();}catch(e){notifications.push(errorMessage(e),'error');}}
function trend(field){const values=body.value.data.map(item=>item[field]).filter(value=>value!=null).map(Number);if(values.length<2)return 'Sin tendencia';const delta=values.at(-1)-values.at(-2);return Math.abs(delta)<.05?'Estable':`${delta>0?'Sube':'Baja'} ${Math.abs(delta).toFixed(1)}`;}
const change=(current,initial)=>current!=null&&initial!=null?(Number(current)-Number(initial)).toFixed(1):'-';
const recommendationLabels={calibrate:'Calibracion',increase_weight:'Aumentar peso',increase_repetitions:'Aumentar repeticiones',maintain:'Mantener',reduce_weight:'Reducir peso',increase_rest:'Aumentar descanso',possible_deload:'Posible descarga',manual_review:'Revisión manual'};
const recommendationLabel=type=>recommendationLabels[type]||type;
const confidenceLabels={low:'Baja',medium:'Media',high:'Alta'};
const confidenceLabel=value=>confidenceLabels[value]||value;
async function loadVolume(){if(volume.value||volumeLoading.value)return;volumeLoading.value=true;try{volume.value=(await api.get('/progress/weekly-volume',{params:{weeks:4}})).data;}catch(e){notifications.push(errorMessage(e),'error');}finally{volumeLoading.value=false;}}
watch(tab,value=>{if(value==='volume')loadVolume();});
const volumeNow=muscle=>muscle.weeks.at(-1)||0;
const volumeBar=sets=>`${Math.min(100,sets/((volume.value?.target.max)||20)*100)}%`;
const volumeMark=()=>`${((volume.value?.target.min)||10)/((volume.value?.target.max)||20)*100}%`;
function volumeStatus(muscle){const min=volume.value.target.min,max=volume.value.target.max,now=volumeNow(muscle);if(now>max)return{text:`${now-max} por encima del rango`,tone:'over'};if(now>=min)return{text:'En rango',tone:'ok'};return{text:`Faltan ${min-now} para el mínimo`,tone:'low'};}
onMounted(load);
</script>
<template><div><header class="page-header"><div><div class="eyebrow">Evidencia personal</div><h1>Progreso</h1><p>Cintura, rendimiento y adherencia cuentan más que una sola cifra.</p></div><button class="btn btn-primary" @click="openMeasurement()"><i class="fa-solid fa-plus"/>Medicion</button></header>
  <div class="segmented-control mb-4"><button v-for="item in [['overview','Resumen'],['body','Cuerpo'],['exercise','Ejercicio'],['volume','Volumen'],['achievements','Logros']]" :key="item[0]" :class="{active:tab===item[0]}" @click="tab=item[0]">{{ item[1] }}</button></div><LoadingSkeleton v-if="loading"/><template v-else>
    <div v-if="tab==='overview'"><section class="grid stats-grid"><article class="stat-card"><span class="stat-icon"><i class="fa-solid fa-dumbbell"/></span><strong>{{ overview.completed_sessions||0 }}</strong><small>Sesiones en la fase</small></article><article class="stat-card"><span class="stat-icon"><i class="fa-solid fa-weight-scale"/></span><strong>{{ change(body.summary.current_weight,body.summary.initial_weight) }}</strong><small>Cambio de peso (kg)</small></article><article class="stat-card streak"><span class="stat-icon"><i class="fa-solid fa-ruler"/></span><strong>{{ change(body.summary.current_waist,body.summary.initial_waist) }}</strong><small>Cambio de cintura (cm)</small></article><article class="stat-card"><span class="stat-icon"><i class="fa-solid fa-trophy"/></span><strong>{{ overview.records?.length||0 }}</strong><small>Records activos</small></article></section><section class="surface panel section-block"><div class="section-heading"><div><h2>Actividad de las últimas 16 semanas</h2><p>La racha se mide por semanas completas, no por días consecutivos.</p></div></div><ActivityCalendar :items="activity"/></section><section class="section-block"><div class="section-heading"><div><h2>Recomendaciones aplicadas</h2><p>Tu entrenador IA las publica y pasan a ser tus objetivos al instante.</p></div></div><div v-if="recommendations.length" class="recommendation-list"><article v-for="item in recommendations" :key="item.id" class="recommendation-row"><div class="d-flex justify-content-between gap-2"><strong>{{ item.exercise.name }}<small v-if="item.target_sets" class="text-secondary"> · {{ item.target_sets }} series</small></strong><span class="d-flex gap-1"><span v-if="item.metadata_json?.source==='assistant'" class="badge-soft green">IA</span><span class="badge-soft blue">{{ confidenceLabel(item.confidence) }}</span></span></div><p class="small text-secondary my-2">{{ item.reason }}</p><small class="text-secondary">{{ formatDay(item.accepted_at||item.created_at) }}</small></article></div><EmptyState v-else title="Sin recomendaciones aplicadas" text="Pídele a tu entrenador IA un análisis para recibir recomendaciones." icon="fa-lightbulb"/></section></div>
    <div v-else-if="tab==='body'">
      <section class="surface panel">
        <div class="section-heading"><div><h2>Resumen corporal</h2><p>Del primer registro al más reciente.</p></div></div>
        <table class="compare">
          <thead><tr><th scope="col"><span class="visually-hidden">Medida</span></th><th scope="col">Inicial</th><th scope="col">Actual</th><th scope="col">Cambio</th><th scope="col"><span class="visually-hidden">Tendencia</span></th></tr></thead>
          <tbody>
            <tr v-for="row in compareRows" :key="row.label">
              <th scope="row">{{ row.label }} <small class="text-secondary">{{ row.unit }}</small></th>
              <td>{{ fmt(row.initial) }}</td>
              <td>{{ fmt(row.current) }}</td>
              <td :class="row.deltaClass">{{ row.delta }}</td>
              <td :title="row.trend.label"><i class="fa-solid" :class="row.trend.icon" :aria-label="row.trend.label" role="img" /></td>
            </tr>
          </tbody>
        </table>
      </section>
      <section v-if="hasComposition" class="surface panel section-block"><div class="section-heading"><div><h2>Composición corporal</h2><p>Tendencia de grasa y músculo según tus escaneos.</p></div></div><LineChart :labels="bodyLabels" :datasets="compositionDatasets"/></section>
      <div class="grid two-column section-block">
        <section class="surface panel"><div class="section-heading"><div><h2>Peso y cintura</h2><p>El peso no es la única señal de éxito. Peso a la izquierda (kg), cintura a la derecha (cm).</p></div></div><LineChart :labels="bodyLabels" :datasets="bodyDatasets"/></section>
        <section class="surface panel">
          <div class="section-heading"><h2>Mediciones</h2></div>
          <div v-if="body.data.length" class="measurement-list">
            <div v-for="item in [...body.data].reverse()" :key="item.id" class="measurement-row">
              <div><strong>{{ formatDay(item.recorded_on) }}</strong><small v-if="item.notes" class="d-block text-secondary">{{ item.notes }}</small></div>
              <span class="values">{{ fmt(item.body_weight_kg) }} kg · {{ fmt(item.waist_cm) }} cm<template v-if="item.body_fat_percentage!=null"> · {{ fmt(item.body_fat_percentage) }}% grasa</template><template v-if="item.skeletal_muscle_mass_kg!=null"> · {{ fmt(item.skeletal_muscle_mass_kg) }} kg músculo</template></span>
              <div class="actions"><button class="icon-button compact" title="Editar" aria-label="Editar medición" @click="openMeasurement(item)"><i class="fa-solid fa-pen"/></button><button class="icon-button compact" title="Eliminar" aria-label="Eliminar medición" @click="removeMeasurement(item)"><i class="fa-solid fa-trash"/></button></div>
            </div>
          </div>
          <EmptyState v-else title="Sin línea base" text="Registra peso, cintura o ambos para iniciar la gráfica." icon="fa-ruler"/>
        </section>
      </div>
    </div>
    <div v-else-if="tab==='exercise'"><div class="surface panel mb-3"><label class="form-label">Ejercicio</label><select v-model="selectedExercise" class="form-select" @change="loadExercise"><option v-for="item in exercises" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><template v-if="exerciseData"><section class="grid stats-grid mb-3"><article class="stat-card"><strong>{{ exerciseData.series.at(-1)?.max_weight||0 }}</strong><small>Peso máximo</small></article><article class="stat-card"><strong>{{ exerciseData.series.at(-1)?.total_repetitions||0 }}</strong><small>Reps totales</small></article><article class="stat-card"><strong>{{ Number(exerciseData.series.at(-1)?.volume||0).toFixed(0) }}</strong><small>Volumen</small></article><article class="stat-card"><strong>{{ Number(exerciseData.series.at(-1)?.estimated_one_rep_max||0).toFixed(1) }}</strong><small>1RM estimado</small></article><article class="stat-card"><strong>{{ exerciseData.series.at(-1)?.average_rir?.toFixed(1)??'-' }}</strong><small>RIR promedio</small></article><article class="stat-card"><strong>{{ exerciseData.calibration.complete?'Activo':'Calibrando' }}</strong><small>{{ exerciseData.calibration.exposures }} exposiciones</small></article><article class="stat-card"><strong>{{ formatDay(exerciseData.series.at(-1)?.date) }}</strong><small>Última sesión</small></article><article class="stat-card"><strong>{{ exerciseData.series.at(-1)?.best_set?`${exerciseData.series.at(-1).best_set.weight} x ${exerciseData.series.at(-1).best_set.repetitions}`:'-' }}</strong><small>Mejor serie</small></article></section><section v-if="exerciseData.recommendation" class="recommendation-row mb-3"><span class="badge-soft blue">{{ confidenceLabel(exerciseData.recommendation.confidence) }}</span><strong class="d-block mt-2">{{ recommendationLabel(exerciseData.recommendation.recommendation_type) }}</strong><p class="small text-secondary mb-0 mt-1">{{ exerciseData.recommendation.reason }}</p></section><section class="surface panel"><LineChart :labels="exerciseLabels" :datasets="exerciseDatasets" empty-text="Completa dos exposiciones para ver la tendencia."/></section><p class="small text-secondary mt-3">El volumen es una referencia util dentro del mismo ejercicio, pero no siempre es comparable entre maquinas o movimientos distintos.</p></template></div>
    <div v-else-if="tab==='volume'">
      <section class="surface panel">
        <div class="section-heading"><div><h2>Series por músculo</h2><p>Series efectivas de esta semana (lunes a domingo). El rango útil es de {{ volume?.target.min ?? 10 }} a {{ volume?.target.max ?? 20 }} series por músculo.</p></div></div>
        <LoadingSkeleton v-if="volumeLoading || !volume"/>
        <ul v-else class="volume-list">
          <li v-for="muscle in volume.muscles" :key="muscle.id" class="volume-row">
            <div class="volume-head"><strong>{{ muscle.name }}</strong><span class="num" :class="volumeStatus(muscle).tone">{{ volumeNow(muscle) }}<small> / {{ volume.target.min }}</small></span></div>
            <div class="volume-bar" role="img" :aria-label="`${muscle.name}: ${volumeNow(muscle)} series esta semana, mínimo ${volume.target.min}`"><span :class="volumeStatus(muscle).tone" :style="{width:volumeBar(volumeNow(muscle))}"/><i :style="{left:volumeMark()}"/></div>
            <div class="volume-foot"><span :class="volumeStatus(muscle).tone">{{ volumeStatus(muscle).text }}</span><span>Plan completo: {{ muscle.planned }}/sem · anteriores: {{ muscle.weeks.slice(0,-1).reverse().join(' · ') || '—' }}</span></div>
          </li>
        </ul>
        <p class="small text-secondary mt-3 mb-0">Cuenta series efectivas (no calentamientos) por el músculo principal de cada ejercicio; el trabajo indirecto —como el tríceps en los press— no suma. "Plan completo" es lo que da la rutina si haces los 4 días.</p>
      </section>
    </div>
    <div v-else-if="tab==='achievements'"><div class="grid achievement-grid"><article v-for="item in achievements" :key="item.id" class="stat-card" :class="{locked:!item.unlocked_at}"><span class="stat-icon"><i class="fa-solid" :class="item.icon"/></span><strong style="font-size:16px">{{ item.name }}</strong><small>{{ item.description }}</small><span class="badge-soft mt-3" :class="item.unlocked_at?'green':''">{{ item.unlocked_at?'Desbloqueado':`${item.xp_reward} XP` }}</span></article></div></div>
  </template>
  <BaseModal :open="measurementOpen" :title="editingMeasurement?'Editar medición':'Nueva medición'" @close="measurementOpen=false"><form id="measurement-form" class="field-grid" @submit.prevent="saveMeasurement"><div class="grid-column-full"><label class="form-label">Fecha</label><input v-model="measurement.recorded_on" class="form-control" type="date" required/></div><div><label class="form-label">Peso (kg)</label><input v-model.number="measurement.body_weight_kg" class="form-control" type="number" min="20" max="500" step=".01" placeholder="Opcional"/></div><div><label class="form-label">Cintura (cm)</label><input v-model.number="measurement.waist_cm" class="form-control" type="number" min="30" max="300" step=".1" placeholder="Opcional"/></div><div><label class="form-label">Grasa corporal (%)</label><input v-model.number="measurement.body_fat_percentage" class="form-control" type="number" min="0" max="70" step=".1" placeholder="Opcional"/></div><div><label class="form-label">Masa grasa (kg)</label><input v-model.number="measurement.fat_mass_kg" class="form-control" type="number" min="0" max="200" step=".1" placeholder="Opcional"/></div><div><label class="form-label">Masa magra (kg)</label><input v-model.number="measurement.lean_mass_kg" class="form-control" type="number" min="0" max="200" step=".1" placeholder="Opcional"/></div><div><label class="form-label">Músculo esqueletico (kg)</label><input v-model.number="measurement.skeletal_muscle_mass_kg" class="form-control" type="number" min="0" max="200" step=".1" placeholder="Opcional"/></div><div><label class="form-label">Agua corporal (kg)</label><input v-model.number="measurement.total_body_water_kg" class="form-control" type="number" min="0" max="200" step=".1" placeholder="Opcional"/></div><div><label class="form-label">Nivel grasa visceral</label><input v-model.number="measurement.visceral_fat_level" class="form-control" type="number" min="1" max="20" step="1" placeholder="Opcional"/></div><div><label class="form-label">Metabolismo basal (kcal)</label><input v-model.number="measurement.basal_metabolic_rate_kcal" class="form-control" type="number" min="0" max="5000" step="1" placeholder="Opcional"/></div><div class="grid-column-full"><label class="form-label">Notas</label><textarea v-model="measurement.notes" class="form-control" rows="3"/></div></form><template #footer><button class="btn btn-outline-light" @click="measurementOpen=false">Cancelar</button><button form="measurement-form" class="btn btn-primary"><i class="fa-solid fa-floppy-disk"/>Guardar</button></template></BaseModal>
</div></template>
